#include <Arduino.h>

const byte TRIG=8, ECHO=9, LED=13, BUZZ=6;
bool active=false;
unsigned long lastNear=0, episodeStart=0, lastSample=0;
int lastBeepPhase=-1;

bool proximity() {
  digitalWrite(TRIG,LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG,HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG,LOW);
  unsigned long duration=pulseIn(ECHO,HIGH,25000UL);
  if (!duration) return false;
  return duration*0.0343f/2.0f <= 10.0f;
}

void setup() {
  pinMode(TRIG,OUTPUT);
  pinMode(ECHO,INPUT);
  pinMode(LED,OUTPUT);
  pinMode(BUZZ,OUTPUT);
  digitalWrite(TRIG,LOW);
  digitalWrite(LED,LOW);
  noTone(BUZZ);
  Serial.begin(9600);
}

void loop() {
  unsigned long now=millis();
  if (now-lastSample>=60UL) {
    lastSample=now;
    bool near=proximity();
    now=millis();
    if (near) {
      lastNear=now;
      if (!active) {
        active=true;
        episodeStart=now;
        lastBeepPhase=-1;
        Serial.println("welcome");
      }
    }
  }
  now=millis();
  if (active && now-lastNear>=5000UL) {
    active=false;
    digitalWrite(LED,LOW);
    noTone(BUZZ);
    lastBeepPhase=-1;
  }
  if (!active) return;
  unsigned long elapsed=now-episodeStart;
  digitalWrite(LED,((elapsed/100UL)%2UL)==0 ? HIGH : LOW);
  int phase=elapsed<600UL ? (int)(elapsed/100UL) : 6;
  if (phase!=lastBeepPhase) {
    lastBeepPhase=phase;
    if (phase<6 && phase%2==0) tone(BUZZ,2000);
    else noTone(BUZZ);
  }
}
